import { urlFormatString, defaultRequest } from "./Utils/index.js";
import { upload } from "./Utils/upload.js";
import { uploadTemp } from "./Utils/upload-temp.js";
/**
 * AVISO: Antes e adicionar um rota aqui
 * é necessario registrar no types.js
 *
 * @param opts nothing-zero
 * @returns Todas as rotas do Yuta APIS
 */
export function routes(opts) {
    async function executeDefaultMethod(endPoint, params = {}, dataType = 'JSON', methodType = 'WITH_API_PATH') {
        const currentBaseUrl = methodType === 'WITH_API_PATH'
            ? `${opts.baseUrl.replace(/\/+$/, '')}/api`
            : opts.baseUrl;
        return defaultRequest({
            ...opts,
            baseUrl: currentBaseUrl,
            url: urlFormatString(currentBaseUrl, opts.route, endPoint)
        }, dataType, params);
    }
    return {
        stalker: {
            tiktokStalker: (username) => executeDefaultMethod('tiktok', { username })
        },
        outros: {
            ascii: (text) => executeDefaultMethod('ascii', { text }),
            clima: (cidade) => executeDefaultMethod('clima', { cidade }),
            emoji_mix: (emoji1, emoji2) => executeDefaultMethod('emoji-mix', { emoji1, emoji2 }, 'BUFFER'),
            signo: (signo) => executeDefaultMethod('signo', { signo }),
            traduzir: (traduzirOpts) => executeDefaultMethod('traduzir', traduzirOpts),
            ip: (ip) => executeDefaultMethod('ip', { ip }),
            encurtarLink: (url) => executeDefaultMethod('encurtar-link', { url }),
            frasesAmor: () => executeDefaultMethod('frases-amor', null),
            hd: (imagem) => executeDefaultMethod('hd', { imagem }, 'BUFFER'),
            hd2: (imagem) => executeDefaultMethod('hd2', { imagem }, 'BUFFER'),
            totext: (url) => executeDefaultMethod('totext', { url }),
            textImg: (text) => executeDefaultMethod('text2img', { text }, 'BUFFER'),
            meme: () => executeDefaultMethod('meme'),
            buscarLocal: (q) => executeDefaultMethod('buscar-local', { q }),
            shazam: async (bufferOrUrl, opts = { type: 'audio' }) => {
                let url;
                if (typeof bufferOrUrl === 'string') {
                    url = bufferOrUrl;
                }
                else {
                    const arrayBuffer = Buffer.isBuffer(bufferOrUrl) ? new Uint8Array(bufferOrUrl).buffer : bufferOrUrl;
                    url = await uploadTemp(arrayBuffer, opts);
                }
                return executeDefaultMethod('shazam', { url });
            }
        },
        canvas: {
            welcome: (opts) => executeDefaultMethod('welcome', { ...opts }, 'BUFFER', 'NO_API_PATH'),
            bemvindo: (opts) => executeDefaultMethod('bemvindo', { ...opts }, 'BUFFER'),
            cardMusic: (opts) => executeDefaultMethod('cardmusic', { ...opts }, 'BUFFER', 'NO_API_PATH'),
            levelup: (opts) => executeDefaultMethod('levelup', { ...opts }, 'BUFFER', 'NO_API_PATH'),
            ping: (opts) => executeDefaultMethod('ping', { ...opts }, 'BUFFER', 'NO_API_PATH'),
            perfil: (opts) => executeDefaultMethod('perfil', { ...opts }, 'BUFFER', 'NO_API_PATH'),
            goodbye: (opts) => executeDefaultMethod('goodbye', { ...opts }, 'BUFFER'),
            ship: (opts) => executeDefaultMethod('ship', { ...opts }, 'BUFFER'),
            qc: (opts) => executeDefaultMethod('qc', { ...opts }, 'BUFFER', 'NO_API_PATH'),
            saiu: (opts) => executeDefaultMethod('saiu', { ...opts }, 'BUFFER', 'NO_API_PATH'),
        },
        stickers: {
            attp: (text) => executeDefaultMethod('attp', { text }, 'BUFFER'),
            brat: (text) => executeDefaultMethod('brat-img', { text }, 'BUFFER'),
            bratvid: (text) => executeDefaultMethod('brat-vid', { text }, 'BUFFER'),
            figu: () => executeDefaultMethod('figu', null, 'BUFFER'),
            figu_anime: () => executeDefaultMethod('figu_anime', null, 'BUFFER'),
            figu_coreana: () => executeDefaultMethod('figu_coreana', null, 'BUFFER'),
            figu_desenho: () => executeDefaultMethod('figu_desenho', null, 'BUFFER'),
            figu_emoji: () => executeDefaultMethod('figu_emoji', null, 'BUFFER'),
            figu_engracadas: () => executeDefaultMethod('figu_engracadas', null, 'BUFFER'),
            figu_raiva: () => executeDefaultMethod('figu_raiva', null, 'BUFFER'),
            figu_roblox: () => executeDefaultMethod('figu_roblox', null, 'BUFFER')
        },
        noticias: {
            cnn: () => executeDefaultMethod('cnn'),
            esportes: () => executeDefaultMethod('esportes'),
            g1: () => executeDefaultMethod('g1'),
            ibge: () => executeDefaultMethod('ibge'),
            noticias_atuais: () => executeDefaultMethod('noticias-atuais'),
            politica: () => executeDefaultMethod('politica'),
            uol: () => executeDefaultMethod('uol'),
        },
        pesquisas: {
            tiktokSearch: (query) => executeDefaultMethod('tiktok-search', { query }),
            ytsearch: (query) => executeDefaultMethod('yt-search', { query }),
            wiki: (query) => executeDefaultMethod('wiki-search', { query }),
            gitstalk: (query) => executeDefaultMethod('github-stalker', { username: query }),
            filmesSearch: (query) => executeDefaultMethod('filmes-search', { query }),
            lyrics_search: (query) => executeDefaultMethod('lyrics-search', { query }),
            pensador: (query) => executeDefaultMethod('pensador-search', { query }),
            playstore: (nome) => executeDefaultMethod('playstore-search', { nome }),
            wallpaper: (query) => executeDefaultMethod('wallpaper-search', { query }),
            google: (query) => executeDefaultMethod('google-search', { query }),
        },
        downloads: {
            play: (query) => executeDefaultMethod('play-audio2', { query }, 'BUFFER'),
            playvideo: (query) => executeDefaultMethod('play-video2', { query }, 'BUFFER'),
            ytmp3: (url) => executeDefaultMethod('ytaudio2', { url }, 'BUFFER'),
            ytmp4: (url) => executeDefaultMethod('ytvideo2', { url }, 'BUFFER'),
            tiktokdl: (url) => executeDefaultMethod('tiktok-dl', { url }),
            tiktokMp3: (url) => executeDefaultMethod('tiktok-mp3', { url }, 'BUFFER'),
            tiktokMp4: (url) => executeDefaultMethod('tiktok-mp4', { url }, 'BUFFER'),
            instavideo: (url) => executeDefaultMethod('instagram-video', { url }),
            facebook: (url) => executeDefaultMethod('facebook-video', { url }),
            facebookMp3: (url) => executeDefaultMethod('face-mp3', { url }, 'BUFFER'),
            facebookMp4: (url) => executeDefaultMethod('face-mp4', { url }, 'BUFFER'),
            pinterestVideo: (url) => executeDefaultMethod('pinterest-video', { url }),
            pinterest: (query) => executeDefaultMethod('pinterest', { query }, 'BUFFER'),
            pinterestMp3: (url) => executeDefaultMethod('pinterest-mp3', { url }, 'BUFFER'),
            pinterestMp4: (url) => executeDefaultMethod('pinterest-mp4', { url }, 'BUFFER'),
            tiktok_foto: (url) => executeDefaultMethod('tiktok-imagens', { url }),
            mediafire: (url) => executeDefaultMethod('mediafire-dl', { url }),
            spotifyMp3: (url) => executeDefaultMethod('spotify-mp3', { url }, 'BUFFER'),
            spotifyPlay: (query) => executeDefaultMethod('spotify-play', { query })
        },
        ias: {
            gpt: (query) => executeDefaultMethod('gpt', { query }),
            gemini: (query) => executeDefaultMethod('gemini', { query }),
            gemini_pro: (query) => executeDefaultMethod('gemini-pro', { query }),
            geminivoz: (query) => executeDefaultMethod('geminivoz', { query }, 'BUFFER'),
            perplexity_ai: (query) => executeDefaultMethod('perplexity-ai', { query }),
        },
        geradores: {
            nick: (query) => executeDefaultMethod('gerar-nicks', { text: query }),
            qrcode: (query) => executeDefaultMethod('qrcode', { text: query }, 'BUFFER')
        },
        animes: {
            hentai_video: () => executeDefaultMethod('hentai-video'),
            hentai_video2: () => executeDefaultMethod('hentai-video2'),
            metadinha: () => executeDefaultMethod('metadinha'),
            quotesanimes: () => executeDefaultMethod('quotesanimes')
        },
        upload: {
            execute: (buffer, name, mimeType) => {
                if (!Buffer.isBuffer(buffer)) {
                    throw new Error('O Upload precisa de um BUFFER válido');
                }
                opts.baseUrl = opts.baseUrl + '/api';
                return upload(buffer, name, {
                    ...opts,
                    url: urlFormatString(opts.baseUrl, 'upload')
                }, mimeType);
            }
        },
        logos: {
            generate: (nomeDoEfeito, textoPraLogo) => {
                if (!textoPraLogo) {
                    console.error('Ei você errou aí na função de logos, você primeiro tem que passar o nome do efeito (tipo: glitch) e depois o texto a ser gerado: (ex: Yuta APis)');
                    throw new Error('Invalid params');
                }
                return executeDefaultMethod(nomeDoEfeito, { texto: textoPraLogo }, 'BUFFER');
            }
        },
        plaquinhas: {
            generate: (Plaq, TextinhoRs) => {
                if (!TextinhoRs) {
                    console.error('Ei você errou aí na função de plaquinha, você primeiro tem que passar o nome da plaq (tipo: plaq1) e depois o texto a ser gerado: (ex: Yuta APis)');
                    throw new Error('Invalid params');
                }
                return executeDefaultMethod(Plaq, { query: TextinhoRs }, 'BUFFER');
            }
        }
    };
}
